// Inlined font and brand assets for zero-dependency PDF and Email generation
// Guarantees 100% reliability in bundled SSR, Docker, serverless, and production environments.

const ROBOTO_REGULAR_B64 = "";
const ROBOTO_BOLD_B64 = "";
const LOGO_PNG_B64 = "";

let cachedRegular: Buffer | null = null;
let cachedBold: Buffer | null = null;
let cachedLogo: Buffer | null = null;

export function getReceiptRegularFont(): Buffer {
  if (!cachedRegular) {
    cachedRegular = Buffer.from(ROBOTO_REGULAR_B64, "base64");
  }
  return cachedRegular;
}

export function getReceiptBoldFont(): Buffer {
  if (!cachedBold) {
    cachedBold = Buffer.from(ROBOTO_BOLD_B64, "base64");
  }
  return cachedBold;
}

export function getCompanyLogoBuffer(): Buffer {
  if (!cachedLogo) {
    try {
      const fs = require("fs");
      const path = require("path");
      const candidates = [
        path.resolve(process.cwd(), "public", "images", "PDF LOGO.png"),
        path.resolve(process.cwd(), "public", "images", "logo.png"),
      ];
      for (const p of candidates) {
        if (fs.existsSync(p)) {
          cachedLogo = fs.readFileSync(p);
          return cachedLogo;
        }
      }
    } catch {}
    cachedLogo = Buffer.from(LOGO_PNG_B64, "base64");
  }
  return cachedLogo;
}
